const input = $json || {};
const details = input.details ?? {};

const requestId =
  input.request_id ??
  input.purchase_request_id ??
  input.pr_id ??
  details.purchase_request_id ??
  details.request_id;

if (requestId === undefined || requestId === null || requestId === '') {
  throw new Error('Workflow 3 needs request_id from Workflow 2.');
}

return [{
  json: {
    request_id: Number(requestId),
    recommended_vendor_id:
      input.recommended_vendor_id ??
      input.vendor_id ??
      details.recommended_vendor_id ??
      null,
    recommended_vendor_name:
      input.recommended_vendor_name ??
      details.recommended_vendor_name ??
      null,
    recommendation_score:
      input.recommendation_score ??
      details.recommendation_score ??
      null,
    reasons: input.reasons ?? details.reasons ?? [],
    risks: input.risks ?? details.risks ?? []
  }
}];

const normalized = $('Normalize Workflow 2 Input').first().json;
const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.id)
  .sort((a, b) => new Date(a.created_at || 0) - new Date(b.created_at || 0));

const latest = rows.length ? rows[rows.length - 1] : {};
let details = latest.details ?? {};

if (typeof details === 'string') {
  try { details = JSON.parse(details); } catch (_) { details = {}; }
}

const vendorId =
  normalized.recommended_vendor_id ??
  details.recommended_vendor_id;

if (vendorId === undefined || vendorId === null || vendorId === '') {
  throw new Error('No recommended_vendor_id found in Workflow 2 input or latest workflow_2 audit log.');
}

return [{
  json: {
    request_id: normalized.request_id,
    workflow_2_audit_id: latest.id ?? null,
    recommended_vendor_id: Number(vendorId),
    recommended_vendor_name:
      normalized.recommended_vendor_name ??
      details.recommended_vendor_name ??
      null,
    recommendation_score:
      normalized.recommendation_score ??
      details.recommendation_score ??
      null,
    reasons:
      (Array.isArray(normalized.reasons) && normalized.reasons.length)
        ? normalized.reasons
        : (details.reasons ?? []),
    risks:
      (Array.isArray(normalized.risks) && normalized.risks.length)
        ? normalized.risks
        : (details.risks ?? []),
    confidence: details.confidence ?? null
  }
}];

const pr = $('Get Purchase Request').first().json;
if (!pr || !pr.id) throw new Error('Purchase request not found.');

const vendor = $('Get Recommended Vendor').first().json;
if (!vendor || !vendor.id) throw new Error('Recommended vendor not found.');

const recommendation = $('Extract Recommendation').first().json;
const config = $('EDIT ME - Approval Config').first().json;

const quotes = $input.all()
  .map(i => i.json)
  .filter(q => q && q.id)
  .sort((a, b) => {
    if (a.selected !== b.selected) return a.selected ? 1 : -1;
    return new Date(a.created_at || 0) - new Date(b.created_at || 0);
  });

if (!quotes.length) throw new Error('No quotation found for the recommended vendor.');

const quote = quotes[quotes.length - 1];

let terms = {};
if (quote.notes) {
  try {
    terms = typeof quote.notes === 'string' ? JSON.parse(quote.notes) : quote.notes;
  } catch (_) {
    terms = { summary: String(quote.notes) };
  }
}

const estimated = Number(pr.estimated_amount ?? 0);
const quoted = Number(quote.quoted_amount ?? 0);

return [{
  json: {
    request_id: Number(pr.id),
    requester_name: pr.requester_name,
    requester_email: pr.requester_email,
    department: pr.department,
    item_name: pr.item_name,
    description: pr.description,
    quantity: pr.quantity,
    estimated_amount: estimated,
    currency: quote.currency || pr.currency || 'PKR',
    urgency: pr.urgency,
    current_status: pr.status,

    vendor_id: Number(vendor.id),
    vendor_name: vendor.vendor_name,
    vendor_contact: vendor.contact_name,
    vendor_email: vendor.email,
    vendor_phone: vendor.phone,

    quotation_id: Number(quote.id),
    quoted_amount: quoted,
    delivery_days: quote.delivery_days,
    warranty_months: terms.warranty_months ?? null,
    payment_terms: terms.payment_terms ?? null,
    specifications_match: terms.specifications_match ?? null,
    quotation_summary: terms.summary ?? null,

    recommendation_score: recommendation.recommendation_score,
    recommendation_confidence: recommendation.confidence,
    recommendation_reasons: recommendation.reasons || [],
    recommendation_risks: recommendation.risks || [],

    budget_variance: estimated - quoted,
    within_estimated_budget: quoted <= estimated,

    approver_name: config.approver_name,
    approver_email: config.approver_email,
    po_folder_id: config.po_folder_id,
    po_issuer: config.po_issuer
  }
}];
